"""FedHealth ML Service — Prediction Service

Loads a trained model artifact, validates input features against
the saved schema, applies the same preprocessing, and returns
risk predictions with appropriate disclaimers.
"""

import json
from pathlib import Path
from typing import Any, Optional

import joblib
import numpy as np

from ..config import MODELS_DIR


DISCLAIMER = (
    "RESEARCH ESTIMATE ONLY. This prediction is generated by a research model "
    "trained on the PIMA Indians Diabetes dataset for educational purposes. "
    "It is NOT a clinical diagnosis and should not be used as the sole basis "
    "for any medical decision. Please consult a qualified healthcare "
    "professional for medical advice, diagnosis, or treatment."
)


def get_available_models() -> list[dict[str, Any]]:
    """List all available model artifacts with their metadata."""
    if not MODELS_DIR.exists():
        return []

    models = []
    for model_dir in sorted(MODELS_DIR.iterdir(), reverse=True):
        if not model_dir.is_dir():
            continue
        meta_path = model_dir / "metadata.json"
        pipeline_path = model_dir / "pipeline.joblib"
        if meta_path.exists() and pipeline_path.exists():
            with open(meta_path) as f:
                metadata = json.load(f)
            if metadata.get("status") == "ready":
                models.append(metadata)

    return models


def get_latest_model_id() -> Optional[str]:
    """Return the model_id of the most recently created ready model."""
    models = get_available_models()
    if not models:
        return None
    return models[0]["model_id"]


def load_model(model_id: str) -> tuple[Any, dict[str, Any]]:
    """Load a model pipeline and its metadata.

    Raises:
        FileNotFoundError: If the model directory or artifacts are missing.
    """
    model_dir = MODELS_DIR / model_id
    pipeline_path = model_dir / "pipeline.joblib"
    metadata_path = model_dir / "metadata.json"

    if not pipeline_path.exists():
        raise FileNotFoundError(f"Model artifact not found: {model_id}")
    if not metadata_path.exists():
        raise FileNotFoundError(f"Model metadata not found: {model_id}")

    pipeline = joblib.load(pipeline_path)
    with open(metadata_path) as f:
        metadata = json.load(f)

    return pipeline, metadata


def predict(
    features: dict[str, float],
    model_id: Optional[str] = None,
) -> dict[str, Any]:
    """Run a single prediction using a trained model.

    Args:
        features: Dict mapping feature names to numeric values.
        model_id: Specific model to use. If None, uses the latest.

    Returns:
        Dict with prediction, probability, risk_level, model info, disclaimer.

    Raises:
        ValueError: If no model is available or features are missing.
    """
    if model_id is None:
        model_id = get_latest_model_id()
        if model_id is None:
            raise ValueError("No trained model available. Train a model first.")

    pipeline, metadata = load_model(model_id)
    feature_columns: list[str] = metadata["feature_columns"]

    # Validate all required features are present
    missing = [f for f in feature_columns if f not in features]
    if missing:
        raise ValueError(f"Missing required features: {missing}")

    # Build feature array in the EXACT order the model expects
    X = np.array([[features[col] for col in feature_columns]], dtype=np.float64)

    # Apply the same zero→NaN preprocessing as training
    zero_to_nan = metadata.get("preprocessing", {}).get("zero_to_nan_columns", [])
    for i, col in enumerate(feature_columns):
        if col in zero_to_nan and X[0, i] == 0:
            X[0, i] = np.nan

    # Predict
    prediction = int(pipeline.predict(X)[0])
    probabilities = pipeline.predict_proba(X)[0]
    diabetes_probability = round(float(probabilities[1]), 6)

    # Risk level
    if diabetes_probability < 0.3:
        risk_level = "Low"
    elif diabetes_probability < 0.6:
        risk_level = "Moderate"
    else:
        risk_level = "High"

    return {
        "prediction": prediction,
        "probability": diabetes_probability,
        "risk_level": risk_level,
        "risk_label": "Positive (Diabetes indicated)" if prediction == 1 else "Negative (No diabetes indicated)",
        "model_id": model_id,
        "model_version": metadata.get("model_version", "unknown"),
        "model_type": metadata.get("model_type", "unknown"),
        "training_method": metadata.get("training_method", "unknown"),
        "feature_columns": feature_columns,
        "disclaimer": DISCLAIMER,
    }
